(async () => {
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
  const out = { desktop: '__TAURI_INTERNALS__' in window };
  if (!document.querySelector('.pj-title')) {
    const cards = [...document.querySelectorAll('.tb-project-main')];
    if (cards[0]) { cards[0].click(); await sleep(3000); }
  }
  out.opened = document.querySelector('.pj-title')?.textContent || null;

  // ① 抓「保存作品文件」的字节（把原生对话框 stub 掉，避免弹窗挂住）
  let captured = null;
  const origCreate = URL.createObjectURL.bind(URL);
  URL.createObjectURL = (b) => { captured = b; return origCreate(b); };
  const internals = window.__TAURI_INTERNALS__;
  const origInvoke = internals ? internals.invoke : null;
  let calledCmd = null;
  if (internals) {
    internals.invoke = function (cmd, args) {
      calledCmd = cmd;
      if (cmd === 'save_work_file') { out.defaultName = args?.defaultName; out.b64Len = args?.dataB64?.length; return Promise.resolve('D:\\测试目录\\' + args.defaultName); }
      return origInvoke.apply(internals, arguments);
    };
  }
  [...document.querySelectorAll('.pj-head-actions > button')].find((b) => b.textContent.includes('保存作品文件')).click();
  await sleep(2500);
  URL.createObjectURL = origCreate;
  if (internals && origInvoke) internals.invoke = origInvoke;
  out.calledCmd = calledCmd;
  out.gotBlob = !!captured;
  out.size = captured?.size || null;
  out.toast = document.querySelector('.pj-toast')?.textContent || null;

  // ② 回列表，把同一份字节当作用户选的文件喂给「打开作品」
  document.querySelector('.pj-crumb-link')?.click();
  await sleep(1800);
  out.backAtList = !!document.querySelector('.tb-project-main');
  const input = [...document.querySelectorAll('input[type=file]')].find((i) => (i.accept || '').includes('.ecp'));
  out.hasFileInput = !!input;
  if (input && captured) {
    const file = new File([captured], '往返测试.ecp', { type: 'application/zip' });
    const dt = new DataTransfer();
    dt.items.add(file);
    input.files = dt.files;
    input.dispatchEvent(new Event('change', { bubbles: true }));
    await sleep(4000);
    out.notice = document.querySelector('.tb-ok')?.textContent || null;
    out.reopenedTitle = document.querySelector('.pj-title')?.textContent || null;
    out.hasRemixBtn = [...document.querySelectorAll('.pj-head-actions button')].some((b) => b.textContent.includes('做同款'));
  }
  return JSON.stringify(out);
})()
